script.setup:
// simplex-noise gives a flow field on the CPU; particles follow it and leave fading trails.
const { createNoise3D } = await ctx.utils.import("https://esm.sh/simplex-noise@4.0.3");
const N = 12000;
const pos = new Float32Array(N * 3); // x, y, speed
for (let i = 0; i < N; i++) { pos[i * 3] = Math.random(); pos[i * 3 + 1] = Math.random(); }
const gl = ctx.gl;
// Half-float trails fade smoothly to black (8-bit ones get stuck at faint values).
gl.getExtension("EXT_color_buffer_float");
const vao = gl.createVertexArray(), buffer = gl.createBuffer();
gl.bindVertexArray(vao); gl.bindBuffer(gl.ARRAY_BUFFER, buffer);
gl.enableVertexAttribArray(0); gl.vertexAttribPointer(0, 2, gl.FLOAT, false, 12, 0);
gl.enableVertexAttribArray(1); gl.vertexAttribPointer(1, 1, gl.FLOAT, false, 12, 8);
gl.bindVertexArray(null);
Object.assign(ctx.state, {
  noise: createNoise3D(), N, pos, vao, buffer, trails: null,
  fade: ctx.utils.createProgram(ctx.utils.FULLSCREEN_VERTEX_SHADER, '#version 300 es\nprecision highp float; in vec2 v_uv; out vec4 outColor; uniform sampler2D u_prev; uniform float u_fade;\nvoid main(){ outColor = vec4(texture(u_prev, v_uv).rgb * u_fade, 1.0); }'),
  copy: ctx.utils.createProgram(ctx.utils.FULLSCREEN_VERTEX_SHADER, '#version 300 es\nprecision highp float; in vec2 v_uv; out vec4 outColor; uniform sampler2D u_tex;\nvoid main(){ vec3 c = texture(u_tex, v_uv).rgb; outColor = vec4(1.0 - exp(-c * 1.6), 1.0); }'),
  points: ctx.utils.createProgram('#version 300 es\nlayout(location=0) in vec2 a_position; layout(location=1) in float a_speed;\nout float v_speed;\nvoid main(){ v_speed = a_speed; gl_Position = vec4(a_position * 2.0 - 1.0, 0.0, 1.0); gl_PointSize = 1.5; }', '#version 300 es\nprecision highp float; in float v_speed; out vec4 outColor; uniform vec3 u_slow; uniform vec3 u_fast;\nvoid main(){ outColor = vec4(mix(u_slow, u_fast, clamp(v_speed, 0.0, 1.0)) * 0.2, 1.0); }'),
});

script.render:
const s = ctx.state, gl = ctx.gl, u = ctx.uniforms;
const [w, h] = ctx.resolution;
if (!s.trails || s.trails.width !== w || s.trails.height !== h) {
  s.trails = ctx.utils.createPingPong(w, h, { internalFormat: gl.RGBA16F, format: gl.RGBA, type: gl.HALF_FLOAT, filter: gl.LINEAR });
}
const aspect = w / h, t = ctx.time * 0.08, scale = u.u_scale, step = 0.0009 * u.u_speed;
for (let i = 0; i < s.N; i++) {
  const o = i * 3;
  let x = s.pos[o], y = s.pos[o + 1];
  const angle = s.noise(x * scale * aspect, y * scale, t) * Math.PI * 2;
  const n2 = s.noise(x * scale * 2 + 9, y * scale * 2, t);
  x += Math.cos(angle) * step / aspect; y += Math.sin(angle) * step;
  // Respawn particles that leave, or now and then, so the field stays covered.
  if (x < 0 || x > 1 || y < 0 || y > 1 || Math.random() < 0.002) { x = Math.random(); y = Math.random(); }
  s.pos[o] = x; s.pos[o + 1] = y; s.pos[o + 2] = n2 * 0.5 + 0.5;
}
const read = s.trails.read(), write = s.trails.write();
gl.bindFramebuffer(gl.FRAMEBUFFER, write.framebuffer);
gl.viewport(0, 0, w, h);
gl.useProgram(s.fade);
ctx.utils.bindTexture(s.fade, "u_prev", read.texture, 0);
ctx.utils.drawFullscreen(s.fade, { u_fade: u.u_trail });
gl.enable(gl.BLEND); gl.blendFunc(gl.ONE, gl.ONE);
gl.useProgram(s.points);
ctx.utils.setUniforms(s.points, { u_slow: u.u_slow, u_fast: u.u_fast });
gl.bindVertexArray(s.vao); gl.bindBuffer(gl.ARRAY_BUFFER, s.buffer);
gl.bufferData(gl.ARRAY_BUFFER, s.pos, gl.DYNAMIC_DRAW);
gl.drawArrays(gl.POINTS, 0, s.N);
gl.bindVertexArray(null); gl.disable(gl.BLEND);
s.trails.swap();
gl.bindFramebuffer(gl.FRAMEBUFFER, null);
gl.viewport(0, 0, w, h);
gl.useProgram(s.copy);
ctx.utils.bindTexture(s.copy, "u_tex", s.trails.read().texture, 0);
ctx.utils.drawFullscreen(s.copy);
